mapper.update:
update t_ai_chat_session
update_time = sysdate(), title = #{title},
where session_id = #{sessionId}

mapper.select:
select * from (
    select message_id, enterprise_id, session_id, role, content, sources, model,
           token_usage, cost_ms, create_time
    from t_ai_chat_message
    where session_id = #{sessionId}
    order by message_id desc
    limit #{limit}
) t order by t.message_id
